cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check users table schema
const cols = db.prepare(\"PRAGMA table_info(users)\").all();
console.log('users columns:', JSON.stringify(cols.map(c => c.name)));

// Search for Maya Chen
const rows = db.prepare(\"SELECT * FROM users WHERE name LIKE '%Maya%Chen%' OR name LIKE '%maya%chen%'\").all();
console.log('Maya Chen rows:', JSON.stringify(rows, null, 2));
"

